"""Generate numeric findings from audited CSVs; main discussion remains authored."""
from pathlib import Path
import json
import pandas as pd
from analyze import fmt
from revision_analysis import label
ROOT=Path(__file__).resolve().parents[1];O=ROOT/'expansion/analysis'
def lname(s):return label(s).replace('meta-t','meta-$t$')
def synthetics():
 s=pd.read_csv(O/'synthetic_summary.csv');texts=[r'\subsection{Controlled findings}']
 titles={'t':'Student','metat':'heterogeneous meta-$t$','heston':'Heston'}
 for law in ['t','metat','heston']:
  g=s[s.study.eq(law)&s.alpha.eq(.01)&s.model.ne('Historical')];best=g.loc[g.rmse.idxmin()];base=best.empirical_rmse
  texts.append(f"For the {titles[law]} target, {lname(best.model)} has the smallest observed model RMSE at one percent, {best.rmse:.3f}, versus {base:.3f} for the exact empirical estimator. Its paired MSE difference is {best.delta_mse:.3f}, with dataset-level standard error {best.paired_se:.3f}. "+('The fitted model improves on the empirical point estimate in this finite experiment.' if best.rmse<base else 'The exact empirical estimator performs better than every fitted generator in this finite experiment.'))
 m=s[s.study.eq('metat')&s.alpha.eq(.01)].set_index('model');f=m.loc['Flow-meta-t'];t=m.loc['Flow-t']
 texts.append(f"Among flexible models on the heterogeneous target, Flow-meta-$t$ has the lowest observed one-percent RMSE, {f.rmse:.3f}, compared with {t.rmse:.3f} for Flow-t. Its paired MSE difference from the exact empirical estimator is {f.delta_mse:.3f} with standard error {f.paired_se:.3f}. The point estimate supports the residual construction, while the ten-dataset uncertainty limits the strength of a superiority claim.")
 h=s[s.study.eq('heston')&s.alpha.eq(.01)].set_index('model');g=h.loc['VAE-G'];v=h.loc['VAE-H'];w=h.loc['WGAN-t']
 texts.append(f"On Heston, VAE-G and VAE-H have one-percent RMSEs {g.rmse:.3f} and {v.rmse:.3f}. The decoder with exponential-order tails "+('improves the observed finite-level error here' if v.rmse<g.rmse else 'does not improve the observed finite-level error here')+f", showing why the tail theorem and finite-level estimation question must be separated. WGAN-t has RMSE {w.rmse:.3f} and bias {w.bias:.3f}. Its polynomial loss tail, when the positive-ray condition holds, differs from the ideal Heston exponential tail. This mismatch is structurally informative but does not imply the observed one-percent error or its sign.")
 exact=h[~h.index.str.startswith('VAE')&h.nll.notna()];be=exact.loc[exact.nll.idxmin()];vv=h[h.index.str.startswith('VAE')].sort_values('nll').iloc[0]
 texts.append(f"The lowest Heston VAE IWAE-64 NLL is {vv.nll:.3f}, compared with {be.nll:.3f} for the best observed exact-density entry, {lname(be.name)}. "+('The importance-sampling bias works against this VAE ordering in expectation; a single Monte Carlo likelihood estimate still has realization noise.' if vv.nll<be.nll else 'The importance-sampling gap prevents interpreting this estimate as the exact VAE marginal NLL.'))
 texts.append(r'The 0.1\% columns now use one million generated scenarios per fit, and the nonanalytic references use four million. Table~\ref{tab:mc-expanded} separates reference from generator evaluation uncertainty. Paired errors and their cross terms are tabulated in the appendix. The reported best model is selected after observing these ten-dataset summaries; the paired standard errors describe variation and are not multiplicity-adjusted winner certificates. Expanded radial-splice and Heston dependence diagnostics use the same ten fitted datasets, with separate 100,000-scenario evaluations at one percent.')
 texts.append(r'\begin{figure}[htbp]\centering\includegraphics[width=0.98\linewidth]{figures/expanded_paired_mse.pdf}\caption{Paired one-percent ES MSE differences from the exact empirical-training estimator. Negative values favor the fitted model; bars show one standard error across ten independent estimation datasets. Shared reference uncertainty is reported separately. The heterogeneous meta-$t$ panel includes Flow-meta-t.}\label{fig:paired-expanded}\end{figure}')
 (O/'synthetic_findings.tex').write_text('\n\n'.join(texts)+'\n')
def panel(which):
 s=pd.read_csv(O/(which+'_summary.csv'));g=s[s.alpha.eq(.01)].set_index('model');best=g.loc[g.fz0.idxmin()];fhs=g.loc['Historical'];cal=pd.read_csv(O/(which+'_calibration.csv'));cal=cal[cal.alpha.eq(.01)]
 neural=g[g.index.str.startswith(('Flow','VAE','WGAN'))];nb=neural.loc[neural.fz0.idxmin()];sig=neural[(neural.delta_fhs<0)&(neural.p_holm<.05)]
 title='Five-basket findings' if which=='crsp5' else '100-stock findings'
 texts=[r'\subsection{'+title+'}']
 texts.append(f"The best observed one-percent score is {lname(best.name)} at {best.fz0:.4f}, against {fhs.fz0:.4f} for FHS. Its paired score difference is {best.delta_fhs:.4f}, with interval $[{best.low:.4f},{best.high:.4f}]$ and Holm-adjusted $p={best.p_holm:.4f}$. The best observed neural mean is {lname(nb.name)} at {nb.fz0:.4f}. "+('No neural improvement over FHS survives the twelve-contrast within-panel Holm adjustment.' if len(sig)==0 else 'The following neural comparisons improve on FHS after the within-panel Holm adjustment: '+', '.join(lname(x) for x in sig.index)+'.'))
 if which=='crsp5':
  a=g.loc['Flow-t'];b=g.loc['Flow-meta-t']
  texts.append(f"Tail-aware flows provide the clearest constructive risk result. Flow-t improves on FHS by {a.delta_fhs:.4f} (unadjusted $p={a.p:.4f}$), and Flow-meta-$t$ by {b.delta_fhs:.4f} ($p={b.p:.4f}$); their adjusted values are {a.p_holm:.4f} and {b.p_holm:.4f}. Flow-t has {a.hits_percent:.3f}\\% exceedances and normalized ES moment {a.es_moment:.4f}. The corresponding conditional-moment diagnostics do not reject for either seed. These are promising point estimates and unadjusted comparisons, not established superiority over the full tested set.")
 m=g.loc['Meta-t'];hits=cal[cal.model.eq('Meta-t')].sort_values('seed');hittext=' and '.join(str(int(x)) for x in hits.hits);ptext=' and '.join(f'{x:.4f}' for x in hits.kupiec_p)
 exact=g[g.nll.notna()&~g.index.str.startswith('VAE')];bestdens=exact.nll.idxmin()
 texts.append(f"Plain meta-$t$ has joint NLL {m.nll:.4f}"+(' and is the lowest observed exact-density entry' if bestdens=='Meta-t' else f", while {lname(bestdens)} has the lowest observed exact-density NLL, {exact.loc[bestdens,'nll']:.4f}")+f". Its one-percent VaR sequences have {hittext} exceedances against 25.14 expected, with Kupiec $p$-values {ptext}. Its normalized ES moment is {m.es_moment:.4f}. Density fit, portfolio risk scoring, and conditional calibration therefore remain distinct assessment tasks.")
 mc=pd.read_csv(O/(which+'_mcs.csv'));selected=mc[mc.alpha.eq(.01)&mc.block.eq(20)];excluded=selected[selected.p_mcs<.05].model.tolist();members=len(selected)-len(excluded)
 texts.append(f"The 95\\% range-statistic model confidence set retains {members} of the thirteen specifications with 20-day blocks. "+('It excludes '+', '.join(lname(x) for x in excluded)+'. ' if excluded else 'All thirteen remain in the set. ')+r'Membership is not a calibration certificate. The 10- and 40-day block checks, secondary tail level, concentrated portfolios, and common-date crash exclusions are supplied in the appendix and machine-readable results.')
 if which=='crsp100':
  miss=json.loads((O/'missing_audit.json').read_text())
  texts.append(f"The corrected 100-stock experiment requires a full pre-estimation year of observed returns; no artificial cold-start volatility spike enters the retained training samples. The mean missing weight in the equal portfolio is {100*miss['mean_missing_equal_weight']:.3f}\\%, with maximum {100*miss['max_missing_equal_weight']:.2f}\\%. Table~\\ref{{tab:missing100}} reports a fixed-forecast missing-return stress and the {miss['complete_dates']} complete test dates. The extension tests dimensionality in established large-cap universes, not generalization to every equity universe.")
 (O/(which+'_findings.tex')).write_text('\n\n'.join(texts)+'\n')
def filters():
 a=pd.read_csv(O/'filter_comparison.csv');n=int((a.delta<0).sum());sig=a[(a.delta<0)&(a.p_holm<.05)];f=a[a.model.eq('Historical')].iloc[0]
 text=r'\subsection{Conditioning versus generator choice}'+'\n'+f"Switching from diagonal to full-covariance EWMA lowers the observed equal-portfolio score for {n} of the ten specifications. For FHS itself the change is {f.delta:.4f}, with interval $[{f.low:.4f},{f.high:.4f}]$. "+('No score improvement survives the ten-contrast Holm adjustment in this ablation.' if len(sig)==0 else 'Within this exploratory ablation, improvements survive its Holm adjustment for '+', '.join(lname(x) for x in sig.model)+'.')+' The 2020 column makes the common shock episode explicit. A full covariance state is a substantive change in the conditioning model; its effect need not be positive for every innovation generator. This experiment refits every family under the alternate filter instead of attributing filter effects to neural architecture.\n'
 text+=r'\begin{figure}[htbp]\centering\includegraphics[width=0.98\linewidth]{figures/expanded_annual.pdf}\caption{Annual equal-portfolio one-percent score differences from FHS under the primary diagonal filter, for both CRSP panels. Distinct markers retain visibility of close VAE curves. The separate full-covariance refitting ablation is reported in Table~\ref{tab:filters}.}\label{fig:annual-expanded}\end{figure}'+'\n'
 (O/'filter_findings.tex').write_text(text)
def abstract():
 a=pd.read_csv(O/'crsp5_summary.csv');a=a[a.alpha.eq(.01)].set_index('model');b=pd.read_csv(O/'crsp100_summary.csv');b=b[b.alpha.eq(.01)].set_index('model')
 n=a[a.index.str.startswith(('Flow','VAE','WGAN'))];n2=b[b.index.str.startswith(('Flow','VAE','WGAN'))];anysig=((n.p_holm<.05)&(n.delta_fhs<0)).any() or ((n2.p_holm<.05)&(n2.delta_fhs<0)).any()
 best100=b.fz0.idxmin();text=r'''Financial scenario models must distinguish distributional fit from calibrated tail-risk forecasts. We characterize how joint latent noise changes finite ReLU generators: shared elliptical Student noise imposes a common index on every loss projection unbounded above, whereas independent Student coordinates can produce heterogeneous indices. We also give an exact change-of-variables treatment of the established meta-$t$ distribution and a residual flow preserving prescribed logarithmic marginal indices while allowing marginal shapes and the copula to change. The expanded study uses ten independent estimation datasets per synthetic law, common validation VaR--ES checkpoint selection, one million evaluation scenarios per fit, and four-million-scenario nonanalytic references. Empirical forecasts cover five CRSP size baskets and annually selected 100-stock universes over 2,514 dates in 2016--2025. Filtered historical simulation (FHS) is the reference. '''
 text+=f"In the five-basket panel, risk-selected Student and meta-$t$ flows improve mean joint risk scores at the unadjusted level, but not after the specified multiplicity correction. Conditional EVT has the lowest observed score, {a.loc['GARCH-EVT','fz0']:.3f}, versus {a.loc['Historical','fz0']:.3f} for FHS. Plain meta-$t$ retains the best exact density fit there, while its VaR sequences exceed the nominal hit frequency. In 100 dimensions, {lname(best100)} has the lowest observed score, {b.loc[best100,'fz0']:.3f}, against {b.loc['Historical','fz0']:.3f} for FHS. "
 text+=('Some higher-dimensional neural contrasts survive within-panel multiplicity control, with model and calibration qualifications reported explicitly. ' if anysig else 'No neural comparison in either primary panel survives within-panel multiplicity control. ')
 text+=r'''An additional full-covariance refitting study, model confidence sets, conditional-moment diagnostics, crash checks, paired error decompositions, and same-sample oracle likelihoods separate architecture, conditioning, and estimation uncertainty. Tail-aware flexibility can be useful, but density ranking alone does not select a calibrated risk model.'''
 (O/'abstract.tex').write_text(text+'\n')
def verification():
 files=[ROOT/'results/mathematical_checks.json',ROOT/'results/output_checks.json',ROOT/'results/revision/revision_checks.json',ROOT/'expansion/checks_preflight.json',ROOT/'expansion/checks_outputs.json',O/'diagnostic_checks.json']
 counts=[len(json.loads(p.read_text())) for p in files];assert all(all(x['passed'] for x in json.loads(p.read_text())) for p in files)
 pilot=json.loads((ROOT/'expansion/rejected_cold_start/reason.json').read_text())
 text=r'\section{Reproducibility and executed verification}'+'\n'+f"The retained expanded design contains 700 model evaluations and 500 fresh neural fits: 300 controlled-law evaluations, 200 five-basket annual-fold/seed evaluations, 100 100-stock evaluations, and 100 full-covariance five-basket evaluations. The original 380 evaluations and 272 neural fits remain archived. The {pilot['completed_rejected_evaluations']} completed cold-start pilot evaluations are excluded from the retained comparison and identified separately. Thirty new high-dimensional portfolio GARCH fits supplement the thirty five-basket fits.\n\n"
 text+=f"All {sum(counts)} recorded checks pass: {counts[0]} original mathematical/software checks, {counts[1]} original output/data checks, {counts[2]} first-revision checks, {counts[3]} common-selection and universe checks, {counts[4]} expanded-output checks, and {counts[5]} ancillary-diagnostic checks. The assertions cover flow inversion, density and ES identities, checkpoint round trips, common FZ0 selection, exact fractional empirical ES, chronological splits, pre-estimation history, finite arrays, correlation matrices, forecast accounting, paired error decomposition, inference coherence, and an independent full-covariance FHS identity. Passing these checks establishes their numerical contracts, not universal predictive superiority.\n\n"
 text+=r'''The entry point is \path{code/run_all.py}. Output mode reconstructs tables, figures, diagnostics, and findings from saved results; experiment mode reruns the fixed expanded design and reuses completed records. The protocol, dated amendments, source hashes, environments, selected checkpoints, validation traces, forecast files, universe memberships, missingness masks, and reference samples are included. Raw licensed CRSP inputs are not redistributed; their names and hashes support reconstruction with authorized data. The cold-start pilot is preserved for audit and is never included by the primary analysis scripts.'''
 (O/'verification.tex').write_text(text+'\n')
def main():
 synthetics();panel('crsp5');panel('crsp100');filters();abstract();verification();print('Expanded findings written')
if __name__=='__main__':main()
